def get_divisors(n):
    divs = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def tau(n):
    return len(get_divisors(n))

def solve_task(N_max=500):
    results = []
    print(f"Starting systematic test up to n = {N_max}")
    for n in range(1, N_max + 1):
        tau_n = tau(n)

        if 5 <= tau_n <= 10:
            divs = get_divisors(n)

            # Since tau(n) >= 5, divs has at least 5 elements (indices 0 to 4).
            a = divs[1] # Second smallest
            b = divs[2] # Third smallest
            c = divs[4] # Fifth smallest

            # Check the condition: n = ab + ac + bc
            required_n = a * b + a * c + b * c

            if required_n == n:
                results.append((n, tau_n))
                print(f"Success found: n={n}, tau(n)={tau_n}, a={a}, b={b}, c={c}. Check: {required_n} = {n}")

    return results

successful_pairs = solve_task(N_max=500)
print("\n--- Final successful pairs (n, tau(n)) found ---")
for pair in successful_pairs:
    print(pair)
